parameters.jsCode:
const body = $input.item.json.body || $input.item.json;

const name = (body.name || '').trim();
const email = (body.email || '').trim().toLowerCase();
const service = (body.service || 'autre').trim();
const message = (body.message || '').trim();
const date = body.date || new Date().toISOString();
const source = body.source || 'netroia.tech';
const ip = ($input.item.json.headers && $input.item.json.headers['x-forwarded-for']) || 'unknown';

// Validation minimale
if (!name || name.length < 2) throw new Error('Champ name invalide ou manquant');
if (!email || !email.includes('@')) throw new Error('Champ email invalide ou manquant');
if (!message || message.length < 10) throw new Error('Champ message trop court');

return [{
  json: { name, email, service, message, date, source, ip }
}];

parameters.text:
=Tu dois analyser la demande de ce prospect et la classifier selon le schéma JSON fourni.

--- DONNÉES PROSPECT ---
Nom : {{ $json.name }}
Email : {{ $json.email }}
Service demandé : {{ $json.service }}
Message : {{ $json.message }}
Date : {{ $json.date }}

--- OFFRES NETROIA ---
- starter (500€-1000€) : Automatisation simple ou agent IA de base
- avance (1200€-2500€) : Workflows complexes, intégrations multi-outils
- sur_mesure (5000€-10000€) : Système agentique complet, architecture IA
- personnalise (sur devis) : Automatisation + Agent IA + Webdesign combinés

Réponds UNIQUEMENT avec le JSON structuré demandé, aucun texte autour.

parameters.inputSchema:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "urgence": {
      "type": "string",
      "enum": ["haute", "normale", "basse"],
      "description": "Niveau d'urgence de la demande"
    },
    "type_besoin": {
      "type": "string",
      "enum": ["automatisation", "agent_ia", "site_web", "combine", "autre"],
      "description": "Type de besoin principal détecté"
    },
    "budget_estime": {
      "type": "string",
      "enum": ["starter", "avance", "sur_mesure", "personnalise"],
      "description": "Pack NetroIA correspondant au budget estimé"
    },
    "resume_besoins": {
      "type": "string",
      "description": "Résumé du besoin en 2-3 phrases maximum"
    },
    "actions_suggerees": {
      "type": "array",
      "items": { "type": "string" },
      "description": "3 actions concrètes prioritaires pour Jordan"
    },
    "score_lead": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Score de qualité du lead (1=froid, 10=prêt à signer)"
    }
  },
  "required": ["urgence", "type_besoin", "budget_estime", "resume_besoins", "actions_suggerees", "score_lead"]
}

