parameters.jsCode:
const data = $input.item.json;
const emailOutput = data.output || {};

// Capitalisation du pack
const packLabels = {
  starter: 'Pack Starter (500€ – 1 000€)',
  avance: 'Pack Avancé (1 200€ – 2 500€)',
  sur_mesure: 'Pack Sur Mesure (5 000€ – 10 000€)',
  personnalise: 'Pack Personnalisé (sur devis)'
};

const packLabel = packLabels[data.budget_estime] || data.budget_estime;

const missionDoc = `# FICHE PROSPECT — ${data.name}

## Informations Client
- **Nom** : ${data.name}
- **Email** : ${data.email}
- **Service demandé** : ${data.service}
- **Date** : ${new Date(data.date).toLocaleString('fr-FR')}
- **Source** : netroia.tech

## Message Original
${data.message}

## Analyse IA du Besoin
- **Type de besoin** : ${data.type_besoin}
- **Urgence** : ${data.urgence}
- **Score Lead** : ${data.score_lead}/10
- **Pack recommandé** : ${packLabel}

### Résumé
${data.resume_besoins}

## Actions Prioritaires pour Jordan
${data.actions_suggerees.split(' | ').map((a, i) => `${i+1}. ${a}`).join('\n')}

## Email Envoyé
**Objet** : ${emailOutput.email_subject || 'N/A'}

---
*Généré automatiquement par NetroIA CRM — ${new Date().toISOString()}*
`;

return [{
  json: {
    ...data,
    email_subject: emailOutput.email_subject || `Votre demande NetroIA — ${data.name}`,
    email_body_html: emailOutput.email_body_html || '<p>Merci pour votre message.</p>',
    mission_doc: missionDoc,
    pack_label: packLabel
  }
}];

